import {state,DEMO} from '../../core/state.js?v=2a0a4e3abb7b';
import {api} from '../../core/api.js?v=2a0a4e3abb7b';
import {refresh} from '../../core/events.js?v=2a0a4e3abb7b';
import {T,esc,icon,heading,btn,panel,field,select,formEnd,modal,closeModal,toast,nativeRequired} from '../../core/ui.js?v=2a0a4e3abb7b';
let invitations=[];export async function load(){invitations=state.workspace.project.can_manage?(await api('studio/invite?project='+state.workspace.project.id)).invitations:[];}
export function render(){const s=state.workspace;return heading(T('Thành viên & phân quyền','Members & access'),T('Cộng tác bằng tài khoản riêng; quyền được giới hạn theo dự án.','Collaborate with separate accounts and project-scoped permissions.'),s.project.can_manage?btn(T('Thêm tài khoản có sẵn','Add existing account'),'members:add','','users')+btn(T('Mời qua liên kết / email','Invite by link / email'),'members:invite','primary','plus'):'')+panel(T('Nhóm dự án','Project team'),`<div class="members-grid">${s.members.map((m,i)=>`<article class="member-card"><span class="member-avatar">${esc(m.name.split(' ').slice(-2).map(s=>s[0]).join(''))}</span><div><h3>${esc(m.name)}</h3><p>@${esc(m.username)}</p><span class="badge ${m.role==='manager'?'blue':'green'}">${m.role==='manager'?T('Quản lý','Manager'):T('Người gán nhãn','Annotator')}</span></div>${s.project.can_manage&&m.id!==s.project.owner?btn(T('Quyền','Access'),'members:edit','sm','settings',`data-id="${m.id}"`):''}</article>`).join('')}</div>`,T('Người gán chỉ sửa quyết định của mình; quản lý cấu hình và phân xử.','Annotators edit their own decisions; managers configure and adjudicate.'))+(s.project.can_manage?panel(T('Lời mời của dự án','Project invitations'),invitations.length?`<div class="table-wrap"><table><thead><tr><th>Email</th><th>Role</th><th>${T('Trạng thái','Status')}</th><th></th></tr></thead><tbody>${invitations.map(v=>`<tr><td>${esc(v.email)}</td><td>${esc(v.role)}</td><td>${v.revoked?T('Đã thu hồi','Revoked'):v.accepted?T('Đã nhận','Accepted'):T('Chờ / có hạn','Pending / time-limited')}</td><td>${!v.revoked&&!v.accepted?btn(T('Thu hồi','Revoke'),'members:revoke','sm danger','',`data-id="${v.id}"`):''}</td></tr>`).join('')}</tbody></table></div>`:`<p class="form-hint">${T('Chưa có lời mời.','No invitations yet.')}</p>`):'')+`<div class="info-banner mt24">${icon('users',18)}<span>${DEMO?T('Demo có TV1 quản lý, TV2/TV3 gán nhãn. Đổi tài khoản ở menu Tài khoản để thử độ đồng thuận và phân xử.','Demo roles: TV1 manages; TV2/TV3 annotate. Switch users in Account to test agreement and adjudication.'):T('Lời mời hết hạn sau 7 ngày. Chấp nhận bằng tài khoản có email trùng lời mời; xác minh email được áp dụng khi máy chủ yêu cầu.','Invites expire in seven days. Accept using an account with a matching email; verification is enforced when required by the server.')}</span></div>`;}
export async function action(name,el){if(name==='revoke'){await api('studio/invite',{project:state.workspace.project.id,action:'revoke',id:Number(el.dataset.id)});await refresh();return;}if(name==='add')modal(T('Thêm tài khoản vào dự án','Add an account to the project'),`<form data-submit="members:add">${field('username',T('Tên tài khoản đã đăng ký','Existing username'),'','text','required')}${formEnd(T('Thêm thành viên','Add member'))}</form>`);if(name==='invite')modal(T('Tạo lời mời','Create invitation'),`<form data-submit="members:invite">${field('email',T('Email người được mời','Invitee email'),'','email','required')}${select('role',T('Vai trò','Role'),[['annotator',T('Người gán nhãn','Annotator')],['manager',T('Quản lý','Manager')]],'annotator')}<label class="check-row"><input name="send_email" type="checkbox">${T('Gửi email qua cấu hình máy chủ','Send email using the server configuration')}</label><p class="form-hint">${T('Không chọn gửi email thì ứng dụng chỉ tạo liên kết để bạn tự chia sẻ. Chế độ email file ở máy local ghi thư trong private_data/emails.','Without email delivery, the app only creates a link for you to share. Local file email mode writes messages to private_data/emails.')}</p>${formEnd(T('Tạo lời mời','Create invitation'))}</form>`);if(name==='edit'){const m=state.workspace.members.find(x=>x.id===Number(el.dataset.id));modal(T('Quyền thành viên','Member access'),`<form data-submit="members:edit" data-id="${m.id}"><h3 class="mb16">${esc(m.name)}</h3>${select('role',T('Vai trò','Role'),[['annotator',T('Người gán nhãn','Annotator')],['manager',T('Quản lý','Manager')]],m.role)}${formEnd()}</form><div class="modal-actions">${btn(T('Gỡ khỏi dự án','Remove from project'),'members:remove','danger','',`data-id="${m.id}"`)}</div>`);}if(name==='remove'){if(DEMO){nativeRequired();return;}await api('studio/members',{project:state.workspace.project.id,user_id:Number(el.dataset.id),action:'remove'});closeModal();await refresh();}}
export async function submit(name,f){if(DEMO){nativeRequired();return;}const v=Object.fromEntries(new FormData(f)),project=state.workspace.project.id;if(name==='add')await api('members',{project,...v});if(name==='edit')await api('studio/members',{project,...v,user_id:Number(f.dataset.id)});if(name==='invite'){const r=await api('studio/invite',{project,...v,send_email:f.send_email.checked});modal(T('Liên kết lời mời','Invitation link'),`<p class="form-hint">${T('Chỉ chia sẻ liên kết này với người được mời.','Share this link only with the intended invitee.')}</p><textarea readonly rows="3">${esc(r.url)}</textarea><p class="form-hint">${r.email_sent?T('Đã gửi qua backend email cấu hình.','Sent through the configured email backend.'):T('Chưa gửi email. Bạn tự chia sẻ liên kết này.','No email sent. Share the link yourself.')}</p>`);return;}closeModal();await refresh();toast(T('Đã cập nhật thành viên.','Membership updated.'));}
